/// <summary>
/// Enqueues the <c>AAXWarehouseToolsFeatureEnsure</c> batch task when the AOS starts. Every error is
/// swallowed so the feature ensure can never affect AOS startup.
/// </summary>
public final class AAXWarehouseToolsFeatureEnsureHandler
{
}

Method.Source:
/// <summary>
/// Handles the system startup event by enqueuing the feature ensure on the batch server.
/// </summary>
[SubscribesTo(classStr(ApplicationStartupEventManager), staticDelegateStr(ApplicationStartupEventManager, onSystemStartup))]
public static void onSystemStartup()
{
    // Errors are swallowed so the feature ensure can never fault AOS startup
    try
    {
        AAXWarehouseToolsFeatureEnsure::runOnceInBackground();
    }
    catch (Exception::CLRError)
    {

    }
    catch (Exception::Error)
    {

    }
    catch
    {

    }
}
